function validate([word1, word2]) {
  for (const [name, words] of [['word1', word1], ['word2', word2]]) {
    if (!Array.isArray(words) || words.length < 1 || words.length > 1000) return `${name} needs 1 to 1000 strings.`;
    if (words.some(w => typeof w !== 'string' || w.length < 1 || w.length > 1000)) return `Each string in ${name} has 1 to 1000 characters.`;
    if (words.some(w => !/^[a-z]+$/.test(w))) return `${name} may only use lowercase letters.`;
    if (words.reduce((total, w) => total + w.length, 0) > 1000) return `The strings in ${name} add up to at most 1000 characters.`;
  }
  return null;
}

