function arrayStringsAreEqual(word1, word2) {
  let w1 = 0;
  let c1 = 0;
  let w2 = 0;
  let c2 = 0;

  while (w1 < word1.length && w2 < word2.length) {
    if (word1[w1][c1] !== word2[w2][c2]) {
      return false;
    }
    c1++;
    if (c1 === word1[w1].length) {
      w1++;
      c1 = 0;
    }
    c2++;
    if (c2 === word2[w2].length) {
      w2++;
      c2 = 0;
    }
  }
  return w1 === word1.length && w2 === word2.length;
}

