function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const letters = size === 'large' ? 'abcdefghijklmnopqrstuvwxyz' : rand() < 0.5 ? 'ab' : 'abc';
  const total = size === 'large' ? 900 + pick(101) : 1 + pick(7);
  const randomText = n => Array.from({ length: n }, () => letters[pick(letters.length)]).join('');
  // Cut a string into consecutive non-empty pieces at random places.
  const split = text => {
    const pieces = [];
    let start = 0;
    while (start < text.length) {
      const len = size === 'large' && rand() < 0.3 ? 1 + pick(40) : 1 + pick(size === 'large' ? 4 : 3);
      pieces.push(text.slice(start, start + len));
      start += len;
    }
    return pieces;
  };
  const text = randomText(total);
  let other = text;
  const mode = rand();
  if (mode < 0.2) {
    // Change one character.
    const at = pick(text.length);
    const replacement = letters[(letters.indexOf(text[at]) + 1 + pick(letters.length - 1)) % letters.length];
    other = text.slice(0, at) + replacement + text.slice(at + 1);
  } else if (mode < 0.35 && text.length > 1) {
    // Drop the last character, so one string is a prefix of the other.
    other = text.slice(0, -1);
  } else if (mode < 0.45 && text.length < 1000) {
    // Add one character at the end.
    other = text + letters[pick(letters.length)];
  } else if (mode < 0.55) {
    other = randomText(total);
  }
  return rand() < 0.5 ? [split(text), split(other)] : [split(other), split(text)];
}
